/**
 * O import map com os endereços do motor: os de `imports` e os de cada `scopes`, e as chaves de
 * `scopes`, que também são endereços. Um JSON que não se lê sai como veio, e o navegador o recusa
 * como recusaria o do site.
 */
export function rewriteImportMap(json: string, context: ScramjetContext, meta: URLMeta): string {
	let map: any;
	try {
		map = JSON_parse(json);
	} catch {
		return json;
	}
	if (!map || typeof map !== "object") return json;
	const enderecos = (tabela: any) => {
		if (!tabela || typeof tabela !== "object") return tabela;
		for (const chave in tabela)
			if (typeof tabela[chave] === "string")
				tabela[chave] = rewriteUrl(tabela[chave], context, meta, { isModule: true });

		return tabela;
	};
	enderecos(map.imports);
	if (map.scopes && typeof map.scopes === "object") {
		const escopos: Record<string, unknown> = {};
		for (const escopo in map.scopes)
			escopos[rewriteUrl(escopo, context, meta, { isModule: true })] = enderecos(map.scopes[escopo]);
		map.scopes = escopos;
	}

	return JSON_stringify(map);
}

let indiceDeRegras: Map<string, [number, number][]> | null = null;

/** De cada nome de atributo para as regras de `htmlRules` que o reescrevem: [regra, posição da chave]. */
function regrasPorAtributo(): Map<string, [number, number][]> {
	if (indiceDeRegras) return indiceDeRegras;
	const indice = new Map<string, [number, number][]>();
	htmlRules.forEach((rule, i) => {
		let k = 0;
		for (const attr in rule) {
			if (typeof rule[attr] !== "function") {
				const nome = attr.toLowerCase();
				let lista = indice.get(nome);
				if (!lista) indice.set(nome, (lista = []));
				lista.push([i, k]);
			}
			k++;
		}
	});

	return (indiceDeRegras = indice);
}

function traverseParsedHtml(
	node: any,
	context: ScramjetContext,
	meta: URLMeta
) {
	if (node.name === "base" && node.attribs.href !== undefined) {
		meta.base = new _URL(node.attribs.href, meta.origin);
	}

	if (node.attribs) {
		// As regras que o nó pede, na ordem de `htmlRules` (a do `allow` lê o `src` que a anterior
		// guardou). O índice vai do nome do atributo às regras, e o nó comum, sem atributo de regra,
		// não percorre as regras.
		const indice = regrasPorAtributo();
		let pares: [number, number, string][] | null = null;
		for (const attr in node.attribs) {
			const lista = indice.get(attr);
			if (!lista) continue;
			if (!pares) pares = [];
			for (const [i, k] of lista) pares.push([i, k, attr]);
		}
		if (pares) {
			if (pares.length > 1) pares.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
			for (const [i, , attr] of pares) {
				const rule = htmlRules[i];
				const sel = rule[attr];
				if (typeof sel === "function") continue;
				if (sel !== "*" && !sel.includes(node.name)) continue;
				if (node.attribs[attr] === undefined) continue;
				const value = node.attribs[attr];
				const v = rule.fn(value, context, meta, node.attribs);

				if (v === null) delete node.attribs[attr];
				else node.attribs[attr] = v;
				node.attribs[`scramjet-attr-${attr}`] = value;
			}
		}
	}

	if (node.name === "style" && node.children[0] !== undefined)
		node.children[0].data = rewriteCss(node.children[0].data, context, meta);

	if (
		node.name === "script" &&
		node.attribs.type?.toLowerCase() === "importmap" &&
		node.children[0] !== undefined
	) {
		node.children[0].data = rewriteImportMap(node.children[0].data, context, meta);
	}
	if (
		node.name === "script" &&
		node.attribs &&
		node.children[0] !== undefined
	) {
		const scriptBlockType = getScriptBlockTypeString(
			"type" in node.attribs ? node.attribs.type : undefined,
			"language" in node.attribs ? node.attribs.language : undefined,
			"type" in node.attribs,
			"language" in node.attribs
		);
		if (isScriptType(scriptBlockType)) {
			let js = node.children[0].data;
			const module = isModuleScriptType(scriptBlockType);
			node.attribs["scramjet-attr-script-source-src"] = bytesToBase64(
				TextEncoder_encode(js)
			);
			const htmlcomment = /<!--[\s\S]*?-->/g;
			js = js.replace(htmlcomment, "");
			node.children[0].data = rewriteJs(
				js,
				"(inline script element)",
				context,
				meta,
				module,
				posicaoNoDocumento(node.children[0])
			);
		}
	}

	if (node.name === "meta" && node.attribs["http-equiv"] !== undefined) {
		// A CSP de um `<meta>` é traduzida pela regra de `content` em `htmlRules`.
		if (node.attribs["http-equiv"].toLowerCase() === "refresh") {
			const refresh = parseDeclarativeRefresh(node.attribs.content || "");
			if (refresh && refresh.url !== null && refresh.url.length > 0) {
				const rewritten = rewriteUrl(refresh.url.trim(), context, meta);
				node.attribs.content =
					node.attribs.content.slice(0, refresh.urlStart) +
					rewritten +
					node.attribs.content.slice(refresh.urlEnd);
			}
		}
	}

	if (node.childNodes) {
		for (const childNode in node.childNodes) {
			node.childNodes[childNode] = traverseParsedHtml(
				node.childNodes[childNode],
				context,
				meta
			);
		}
	}

	return node;
}

export function rewriteSrcset(
	srcset: string,
	context: ScramjetContext,
	meta: URLMeta
) {
	// vssh fork: o split original `/ .*,/` usava `.*` GANANCIOSO — casava do 1º espaço até a ÚLTIMA
	// vírgula do srcset inteiro, engolindo todas as imagens do meio e sobrando só a 1ª URL + uma
	// entrada vazia (rewriteUrl resolvia como a própria página → <img> quebrado). Split simples por
	// vírgula tampouco serve: quebra data: URLs (`data:...;base64,AAAA 1x`) que contêm vírgula.
	// Seguimos o algoritmo de parsing de srcset da WHATWG: candidatos separados por vírgula, mas a
	// URL é uma sequência de não-espaços (a vírgula interna do data: fica dentro dela), com a forma
	// sem-espaço `urlA,urlB` tratada por vírgulas à direita da URL.
	const isWs = (c: string) =>
		c === " " || c === "\t" || c === "\n" || c === "\r" || c === "\f";
	const candidates: { url: string; descriptor: string }[] = [];
	let pos = 0;
	const len = srcset.length;
	while (pos < len) {
		while (pos < len && (isWs(srcset[pos]) || srcset[pos] === ",")) pos++;
		if (pos >= len) break;
		const urlStart = pos;
		while (pos < len && !isWs(srcset[pos])) pos++;
		let url = srcset.slice(urlStart, pos);
		let descriptor = "";
		if (url.endsWith(",")) {
			// forma `urlA,urlB` sem espaço: as vírgulas à direita são separadores
			url = url.replace(/,+$/, "");
		} else {
			while (pos < len && isWs(srcset[pos])) pos++;
			const descStart = pos;
			let parenDepth = 0;
			while (pos < len) {
				const c = srcset[pos];
				if (parenDepth === 0 && c === ",") break;
				if (c === "(") parenDepth++;
				else if (c === ")" && parenDepth > 0) parenDepth--;
				pos++;
			}
			descriptor = srcset.slice(descStart, pos).trim();
		}
		if (url) candidates.push({ url, descriptor });
	}

	const rewrittenSources = candidates.map(({ url, descriptor }) => {
		const rewrittenUrl = rewriteUrl(url, context, meta);
		return descriptor ? `${rewrittenUrl} ${descriptor}` : rewrittenUrl;
	});

	return rewrittenSources.join(", ");
}

